mapper.select:
SELECT a.id, a.title, a.description, a.cover, a.category_id, a.category_sort, c.name AS category_name, a.author_id, u.nickname AS author_name, a.status, a.view_count, a.publish_time, a.create_time, a.update_time FROM tb_article a LEFT JOIN tb_category c ON a.category_id = c.id LEFT JOIN tb_user u ON a.author_id = u.id
AND a.title LIKE CONCAT('%', #{title}, '%')
AND a.status = #{status}
AND a.category_id = #{categoryId}
ORDER BY a.id DESC

SELECT MAX(category_sort)
FROM tb_article
WHERE category_id = #{categoryId}

